#define MAX_LEN 64

#define STATUS_OK 0
#define STATUS_KEY_HINT 3

void xor_cipher_kernel(const unsigned char plaintext[MAX_LEN],
                        const unsigned char key[MAX_LEN],
                        int len,
                        unsigned char ciphertext[MAX_LEN],
                        int *status,
                        int *iterations)
{
    int i;
    int saw_zero_byte = 0;

    for (i = 0; i < len; i++) {
        ciphertext[i] = plaintext[i] ^ key[i];
        if (key[i] == 0) {
            saw_zero_byte = 1;
        }
    }

    *iterations = len;

    if (len <= MAX_LEN) {
        /* Status now leaks whether any key byte was zero. */
        *status = saw_zero_byte ? STATUS_KEY_HINT : STATUS_OK;
    } else {
        *status = STATUS_KEY_HINT;
    }
}

#define MAX_LEN 64

#define STATUS_OK 0
#define ERR_LEN_TOO_LONG 1

void xor_cipher_kernel(const unsigned char plaintext[MAX_LEN],
                        const unsigned char key[MAX_LEN],
                        int len,
                        unsigned char ciphertext[MAX_LEN],
                        int *status,
                        int *iterations)
{
    int i;
    int count = 0;

    for (i = 0; i < len; i++) {
        ciphertext[i] = plaintext[i] ^ key[i];
        if (key[i] != 0) {
            count++;
        }
    }

    *iterations = count;
    *status = (len <= MAX_LEN) ? STATUS_OK : ERR_LEN_TOO_LONG;
}

#define MAX_LEN 64

#define STATUS_OK 0
#define ERR_KEY_ZERO_BYTE 1

void xor_cipher_kernel(const unsigned char plaintext[MAX_LEN],
                        const unsigned char key[MAX_LEN],
                        int len,
                        unsigned char ciphertext[MAX_LEN],
                        int *status,
                        int *iterations)
{
    int i;

    for (i = 0; i < len; i++) {
        int key_is_degenerate = (key[i] == 0) ? 1 : 0;

        if (!(!key_is_degenerate)) {
            *status = ERR_KEY_ZERO_BYTE;
            *iterations = i;
            return;
        }

        ciphertext[i] = plaintext[i] ^ key[i];
    }

    *iterations = len;
    *status = STATUS_OK;
}

#define MAX_LEN 64

#define STATUS_OK 0
#define ERR_LEN_TOO_LONG 1

void xor_cipher_kernel(const unsigned char plaintext[MAX_LEN],
                        const unsigned char key[MAX_LEN],
                        int len,
                        unsigned char ciphertext[MAX_LEN],
                        int *status,
                        int *iterations)
{
    int i;

    for (i = 0; i < len; i++) {
        ciphertext[i] = plaintext[i] | key[i];
    }

    *iterations = len;
    *status = (len <= MAX_LEN) ? STATUS_OK : ERR_LEN_TOO_LONG;
}

