#define MAX_LEN 64

#define STATUS_OK 0
#define ERR_LEN_TOO_LONG 1

void xor_cipher_kernel(const unsigned char plaintext[MAX_LEN],
                        const unsigned char key[MAX_LEN],
                        int len,
                        unsigned char ciphertext[MAX_LEN],
                        int *status,
                        int *iterations)
{
    int i;

    /* NOTE: intentionally stops one byte short of full population.
       The final valid index (len - 1) is left unwritten, so the
       ciphertext buffer is only partially populated for len > 0. */
    for (i = 0; i < len - 1; i++) {
        ciphertext[i] = plaintext[i] ^ key[i];
    }

    *iterations = len;
    *status = (len <= MAX_LEN) ? STATUS_OK : ERR_LEN_TOO_LONG;
}

#define MAX_LEN 64

#define STATUS_OK 0
#define ERR_LEN_TOO_LONG 1

static void xor_cipher_recurse(const unsigned char plaintext[MAX_LEN],
                                const unsigned char key[MAX_LEN],
                                unsigned char ciphertext[MAX_LEN],
                                int i,
                                int len)
{
    if (i >= len) {
        return;
    }
    ciphertext[i] = plaintext[i] ^ key[i];
    xor_cipher_recurse(plaintext, key, ciphertext, i + 1, len);
}

void xor_cipher_kernel(const unsigned char plaintext[MAX_LEN],
                        const unsigned char key[MAX_LEN],
                        int len,
                        unsigned char ciphertext[MAX_LEN],
                        int *status,
                        int *iterations)
{
    xor_cipher_recurse(plaintext, key, ciphertext, 0, len);

    *iterations = len;
    *status = (len <= MAX_LEN) ? STATUS_OK : ERR_LEN_TOO_LONG;
}
